// Puzzle data access and scoring rules (pure functions, unit-tested).
//
// Puzzle source: positions generated by Stockfish self-play and verified with
// deeper searches (scripts/mine.mjs, scripts/endgames.mjs): at every step of
// the solution the played move is the only clearly winning (or, for defensive
// puzzles and drawn endgames, the only saving) move. Themes are detected on
// the solution line itself (scripts/tag.mjs).
export interface Puzzle {
  id: string;
  fen: string;
  moves: string[]; // UCI; if !solverFirst, moves[0] is the opponent's move that sets up the puzzle
  solverFirst: boolean;
  themes: string[];
  rating: number;
  idea: string[];
  goal?: "win" | "draw";
}

export interface ThemeInfo {
  id: string;
  label: string;
  desc: string;
}

export const THEMES: ThemeInfo[] = [
  { id: "mateIn1", label: "Mate em 1", desc: "Encontre o lance que dá xeque-mate imediatamente." },
  { id: "mateIn2", label: "Mate em 2", desc: "Uma sequência forçada de dois lances termina em mate." },
  { id: "mateIn3", label: "Mate em 3", desc: "Três lances precisos levam ao mate." },
  { id: "mateIn4", label: "Mate em 4", desc: "Combinações de mate mais longas." },
  { id: "fork", label: "Garfo", desc: "Uma peça ataca duas ou mais peças ao mesmo tempo." },
  { id: "pin", label: "Cravada", desc: "Uma peça não pode sair sem expor outra mais valiosa." },
  { id: "skewer", label: "Espeto", desc: "A peça valiosa da frente é atacada; ao sair, a de trás cai." },
  { id: "discoveredAttack", label: "Ataque descoberto", desc: "Uma peça se move e abre o ataque de outra." },
  { id: "deflection", label: "Desvio de defensor", desc: "Force o defensor a sair da casa que protege." },
  { id: "overloading", label: "Sobrecarga", desc: "Um defensor com tarefas demais não dá conta de todas." },
  { id: "sacrifice", label: "Sacrifício", desc: "Entregue material para ganhar algo maior." },
  { id: "doubleAttack", label: "Ataque duplo", desc: "Duas ameaças ao mesmo tempo: o adversário só defende uma." },
  { id: "hangingPiece", label: "Peça indefesa", desc: "Capture a peça que ficou sem proteção." },
  { id: "winMaterial", label: "Ganho de material", desc: "Uma sequência que ganha material." },
  { id: "defense", label: "Táticas defensivas", desc: "Só um lance salva a posição. Encontre-o." },
  { id: "pawnEndgame", label: "Finais de peões", desc: "Oposição, casas-chave e corridas de peões." },
  { id: "rookEndgame", label: "Finais de torres", desc: "Técnica precisa com torres e peões." },
  { id: "advancedCombo", label: "Combinações avançadas", desc: "Sequências longas com três ou mais lances seus." },
];

export function themeLabel(id: string): string {
  return THEMES.find((t) => t.id === id)?.label ?? id;
}

export const DIFFICULTIES = [
  { id: "facil", label: "Fácil", min: 0, max: 899 },
  { id: "medio", label: "Médio", min: 900, max: 1299 },
  { id: "dificil", label: "Difícil", min: 1300, max: 1699 },
  { id: "avancado", label: "Avançado", min: 1700, max: 9999 },
];

let cache: Promise<Puzzle[]> | null = null;
export function loadPuzzles(): Promise<Puzzle[]> {
  return (cache ??= import("./puzzles.json").then((m) => (m.default ?? m) as unknown as Puzzle[]));
}

/** Elo-style update of the puzzle score (separate from any game rating). */
export function updateRating(user: number, puzzle: number, success: boolean, attempts: number): number {
  const expected = 1 / (1 + Math.pow(10, (puzzle - user) / 400));
  const k = attempts < 20 ? 40 : 24;
  return Math.max(100, Math.round(user + k * ((success ? 1 : 0) - expected)));
}

/**
 * Points reward correctness and consistency, not speed: a clean solve earns a
 * base value plus a difficulty bonus and a capped streak bonus; solving after
 * mistakes earns a little; revealing the answer earns nothing.
 */
export function pointsFor(o: { clean: boolean; solved: boolean; rating: number; streak: number }): number {
  if (!o.solved) return 0;
  if (!o.clean) return 3;
  return 10 + Math.round(o.rating / 200) + Math.min(o.streak, 10);
}

/** Deterministic daily set: one easy, one medium, one hard puzzle. */
export function dailyIds(all: Puzzle[], dateKey: string): string[] {
  let h = 2166136261;
  for (const ch of dateKey) h = Math.imul(h ^ ch.charCodeAt(0), 16777619) >>> 0;
  const out: string[] = [];
  for (const d of [DIFFICULTIES[0], DIFFICULTIES[1], DIFFICULTIES[2]]) {
    const pool = all.filter((p) => p.rating >= d.min && p.rating <= d.max);
    const src = pool.length ? pool : all;
    h = Math.imul(h ^ (h >>> 13), 1274126177) >>> 0;
    const p = src[h % src.length];
    if (p && !out.includes(p.id)) out.push(p.id);
  }
  return out;
}

/** Next training puzzle: unseen, close to the user's score. */
export function pickNext(all: Puzzle[], opts: { rating: number; seen: Set<string>; theme?: string; min?: number; max?: number; exclude?: string }, rnd = Math.random): Puzzle | null {
  let pool = all.filter((p) => p.id !== opts.exclude && (!opts.theme || p.themes.includes(opts.theme)) && (opts.min === undefined || p.rating >= opts.min) && (opts.max === undefined || p.rating <= opts.max));
  if (!pool.length) return null;
  const unseen = pool.filter((p) => !opts.seen.has(p.id));
  if (unseen.length) pool = unseen;
  const sorted = [...pool].sort((a, b) => Math.abs(a.rating - opts.rating) - Math.abs(b.rating - opts.rating));
  const near = sorted.slice(0, Math.max(1, Math.min(12, Math.ceil(sorted.length / 4))));
  return near[Math.floor(rnd() * near.length)];
}

/** Is `uci` an acceptable answer at solution index `i`? Alternative mates are accepted on the final move. */
export function isCorrect(p: Puzzle, i: number, uci: string, givesMate: boolean): boolean {
  if (p.moves[i] === uci) return true;
  return i === p.moves.length - 1 && givesMate && p.themes.some((t) => t.startsWith("mate"));
}
